#!/usr/bin/env python3
"""Validate commit subjects against Conventional Commits 1.0.

Usage:
  check_commit_msg.py <message-file>          (commit-msg hook)
  check_commit_msg.py --range <base>..<head>  (audit/CI; skips merge commits)
"""
import re
import subprocess
import sys

TYPES = "feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert"
PATTERN = re.compile(rf"^({TYPES})(\([a-z0-9][a-z0-9._/-]*\))?!?: \S.*$")
MAX_SUBJECT = 100
# Generated by git/GitHub, not authored.
EXEMPT = re.compile(r"^(Merge |Revert \"|fixup! |squash! )")


def check(subject: str) -> str | None:
    if EXEMPT.match(subject):
        return None
    if not PATTERN.match(subject):
        return (f"not 'type(scope): description' with type in {TYPES.replace('|', '/')}")
    if len(subject) > MAX_SUBJECT:
        return f"subject longer than {MAX_SUBJECT} characters"
    if subject.endswith("."):
        return "subject ends with a period"
    return None


def main(argv: list[str]) -> int:
    if len(argv) == 3 and argv[1] == "--range":
        out = subprocess.run(
            ["git", "log", "--no-merges", "--format=%h %s", argv[2]],
            capture_output=True, text=True, check=True).stdout.splitlines()
        bad = 0
        for line in out:
            sha, _, subject = line.partition(" ")
            err = check(subject)
            if err:
                bad += 1
                print(f"{sha}: {subject}\n    -> {err}")
        print(f"{bad} non-conforming of {len(out)} commits")
        return 1 if bad else 0
    if len(argv) != 2:
        print(__doc__)
        return 2
    with open(argv[1], encoding="utf-8") as fh:
        lines = [l for l in fh.read().splitlines() if not l.startswith("#")]
    subject = lines[0] if lines else ""
    err = check(subject)
    if err:
        print(f"Commit rejected: {err}\n  got: {subject}\n"
              "  e.g. feat(export): add selection dialog | fix(grid)!: drop legacy cache key\n"
              "  See docs/decisions/2026-11-05-conventional-commits.md", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
